function Hd = tx_match_filter_design(osr)
%UNTITLED_TEMP Returns a discrete-time filter object.

% MATLAB Code
% Generated by MATLAB(R) 9.7 and DSP System Toolbox 9.9.
% Generated on: 27-Dec-2019 16:47:54

% FIR Window Raised-cosine filter designed using the FIRRCOS function.

% All frequency values are in MHz.
Fs = 1;  % Sampling Frequency

N    = 64;         % Order
Fc   = 1.3*1/osr/2;    % Cutoff Frequency
TM   = 'Rolloff';  % Transition Mode
R    = 0.15;        % Rolloff
DT   = 'sqrt';     % Design Type
Beta = 0.5;        % Window Parameter

% Create the window vector for the design algorithm.
win = kaiser(N+1, Beta);

% Calculate the coefficients using the FIR1 function.
b  = firrcos(N, Fc/(Fs/2), R, 2, TM, DT, [], win);
Hd = dfilt.dffir(b);
% Set the arithmetic property.
set(Hd, 'Arithmetic', 'fixed', ...
    'CoeffWordLength', 12, ...
    'CoeffAutoScale', true, ...
    'Signed',         true, ...
    'InputWordLength', 12, ...
    'inputFracLength', 11, ...
    'FilterInternals',  'FullPrecision');
normalize(Hd);


% [EOF]
